import { CLINIC_SEARCH_URL } from '../config.js';

export async function liveSearchClinics({ lang = 'zh', location = null, triage = null } = {}) {
  if (!CLINIC_SEARCH_URL) throw new Error('VITE_CLINIC_SEARCH_URL is not set: clinic search is not connected yet.');
  const res = await fetch(CLINIC_SEARCH_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ lang, location, level: triage && triage.level, summary: triage && triage.summary }),
  });
